-- LOCAL ONLY. Full transactional package; rollback refuses source drift or operational use.
BEGIN;SET LOCAL lock_timeout='10s';SET LOCAL search_path=pg_catalog;LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;SELECT pg_advisory_xact_lock(61001,1);LOCK TABLE public.folha_registos,public.folha_referencias,public.folha_referencias_historico,public.folha_avaliacoes_diarias,public.folha_historico,public.folha_gestao_historico,public.folha_conferencias_mensais,public.folha_conferencia_historico,public.folha_vencimentos,public.folha_he,public.ausencias,public.quadro_equipa_permanencias,folha_privado.operacoes IN SHARE ROW EXCLUSIVE MODE;DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.destino_autorizar_v3(uuid,uuid,text,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='c874fba357c974db5241fc0c5c82bf92a2f012e822f8d0fb545b0f18317daa22' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner )) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: folha_privado.destino_autorizar_v3(uuid,uuid,text,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.referencia_guardar_v3()') AND proowner='postgres'::regrole AND prosecdef=false AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e4314ef9836ce96178a50843f8fda176d82210349da6172ae318ea001b07bc2d' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner )) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: folha_privado.referencia_guardar_v3()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.referencia_invariante_v3()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='df2584770792c8f77a6d9c5dc50bd6714ff353671574cf2f94fe2f76b88b0e1a' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner )) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: folha_privado.referencia_invariante_v3()';END IF;END $functions$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
END $functions$;DO $absent$ BEGIN IF to_regprocedure('folha_privado.save_plano_integrado_v3(jsonb,uuid,date,uuid,boolean,jsonb)') IS NOT NULL OR to_regprocedure('folha_privado.referencia_plano_integrado_v3(text,jsonb,boolean,text,jsonb)') IS NOT NULL OR to_regprocedure('public.fn_folha_plano_integrado_v3(jsonb,boolean,text)') IS NOT NULL THEN RAISE EXCEPTION 'ADDON_PRESENT_OR_PARTIAL';END IF;END $absent$;DO $data$ DECLARE r record;j jsonb;BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;IF NOT EXISTS(SELECT 1 FROM pg_namespace WHERE nspname='primeline_plano_integrado_backup' AND nspowner='postgres'::regrole) OR EXISTS(SELECT 1 FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='primeline_plano_integrado_backup' AND a.grantee<>n.nspowner) OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE n.nspname='primeline_plano_integrado_backup' AND a.grantee<>c.relowner) OR EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='primeline_plano_integrado_backup' AND a.attnum>0 AND NOT a.attisdropped AND a.attacl IS NOT NULL AND a.attacl<>'{}'::aclitem[]) THEN RAISE EXCEPTION 'ADDON_BACKUP_NOT_PRIVATE';END IF;FOR r IN SELECT * FROM primeline_plano_integrado_backup.dados LOOP EXECUTE format('SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text COLLATE "C"),''[]''::jsonb) FROM %s x',r.tabela::regclass) INTO j;IF j IS DISTINCT FROM r.linhas THEN RAISE EXCEPTION 'ADDON_DATA_DRIFT';END IF;END LOOP;END $data$;CREATE FUNCTION folha_privado.save_plano_integrado_v3(p jsonb,w uuid,d date,req uuid,confirmar boolean,plano jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
DECLARE u public.utilizadores; person uuid:=(p->'key'->>'person_id')::uuid; kind text:=p->'key'->>'kind'; old public.folha_registos;
 row jsonb; f jsonb; state text; expected integer; window_days integer; special boolean; result public.folha_registos;
BEGIN
 u:=folha_privado.ator(); PERFORM folha_privado.destino_autorizar_v3(person,w,kind,true); PERFORM folha_privado.lock_dia(person,d);
 IF p->'key'->>'work_id' IS DISTINCT FROM w::text OR p->'key'->>'date' IS DISTINCT FROM d::text OR kind IS NULL OR kind NOT IN('primeline','external')
 THEN RAISE EXCEPTION 'VALIDATION_ERROR: chave'; END IF;
 row:=folha_privado.linha(person,w,d,kind); IF kind='primeline' AND EXISTS(SELECT 1 FROM public.ausencias WHERE colaborador_id=person AND data=d) THEN RAISE EXCEPTION 'ABSENCE_CONFLICT';END IF;
 IF kind='primeline' AND EXISTS(SELECT 1 FROM public.ponto_pessoal_obra WHERE colaborador_id=person AND data=d) THEN RAISE EXCEPTION 'LEGACY_CONFLICT: não misturar escritores'; END IF;
 IF kind='primeline' THEN
  PERFORM 1 FROM public.colaboradores WHERE id=person AND empresa_id=u.empresa_id AND data_admissao<=d AND (data_saida IS NULL OR data_saida>d) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: colaborador indisponível' USING ERRCODE='42501'; END IF;
  IF u.funcao='encarregado' AND NOT folha_privado.elegivel_equipa(person,d) AND NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=person AND utilizador_id=u.id AND empresa_id=u.empresa_id AND (SELECT count(*) FROM public.colaboradores WHERE utilizador_id=u.id AND empresa_id=u.empresa_id)=1) THEN RAISE EXCEPTION 'PERMISSION_DENIED: apenas equipa operacional elegível' USING ERRCODE='42501'; END IF;

 ELSE
  PERFORM 1 FROM public.folha_externos WHERE id=person AND empresa_id=u.empresa_id AND (ativo OR (folha_privado.adm_operacional() OR u.funcao='diretor_obra') AND EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.externo_id=person AND f.obra_id=w AND f.data=d AND f.empresa_id=u.empresa_id)) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: externo indisponível' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.folha_externos e JOIN public.fornecedores f ON f.id=e.fornecedor_id WHERE e.id=person AND f.empresa_id=u.empresa_id AND (folha_privado.admin() OR EXISTS(SELECT 1 FROM public.subempreitadas s WHERE s.fornecedor_id=f.id AND s.obra_id=w))) THEN RAISE EXCEPTION 'PERMISSION_DENIED: fornecedor não autorizado' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.folha_externos_dias WHERE externo_id=person AND obra_id=w AND data=d AND empresa_id=u.empresa_id) AND NOT EXISTS(SELECT 1 FROM public.folha_externos_permanencias WHERE externo_id=person AND obra_id=w AND empresa_id=u.empresa_id AND inicio<=d AND (fim IS NULL OR fim>d)) THEN RAISE EXCEPTION 'EXTERNAL_DAY_REQUIRED'; END IF;
 END IF;
 IF row->>'conflict' IS NOT NULL THEN RAISE EXCEPTION '%',row->>'conflict'; END IF;
 SELECT * INTO old FROM public.folha_registos WHERE obra_id IS NOT DISTINCT FROM w AND data=d AND CASE WHEN kind='primeline' THEN colaborador_id=person ELSE externo_id=person END FOR UPDATE;
 IF kind='primeline' AND old.id IS NULL THEN SELECT revision INTO old.revision FROM folha_privado.periodos_revisoes WHERE colaborador_id=person AND obra_id IS NOT DISTINCT FROM w AND data=d; END IF;
 IF kind='external' AND u.funcao='diretor_obra' AND old.id IS NULL THEN RAISE EXCEPTION 'PERMISSION_DENIED: apenas correção externa existente' USING ERRCODE='42501';END IF;
 IF (p->>'expected_revision')::integer IS DISTINCT FROM coalesce(old.revision,0) THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001'; END IF;
 IF d<(now() AT TIME ZONE 'Europe/Lisbon')::date AND NOT folha_privado.adm_operacional() AND NOT(kind='external' AND u.funcao='diretor_obra') THEN
  window_days:=1;
  IF window_days IS NULL THEN RAISE EXCEPTION 'CORRECTION_WINDOW_UNCONFIGURED'; END IF;
  IF (now() AT TIME ZONE 'Europe/Lisbon')::date-d>window_days THEN RAISE EXCEPTION 'CORRECTION_WINDOW_EXCEEDED'; END IF;
 END IF;
 IF (now() AT TIME ZONE 'Europe/Lisbon')::date-d>1 AND folha_privado.adm_operacional() AND nullif(btrim(p->>'reason'),'') IS NULL THEN RAISE EXCEPTION 'CORRECTION_REASON_REQUIRED'; END IF;
 f:=folha_privado.facts(p->'intervals',d); expected:=(row->>'expected_minutes')::integer;
 IF kind='primeline' THEN expected:=NULL;
 ELSIF w IS NOT NULL THEN SELECT sum((extract(epoch FROM ((h.x->>'end')::time-(h.x->>'start')::time))/60)::integer) INTO expected FROM public.folha_horarios schedule CROSS JOIN LATERAL jsonb_array_elements(schedule.intervals) h(x) WHERE schedule.obra_id=w AND EXISTS(SELECT 1 FROM jsonb_array_elements(p->'intervals') period WHERE period->>'period'=h.x->>'period'); END IF;
 special:=extract(isodow FROM d)>5 OR EXISTS(SELECT 1 FROM public.folha_config_empresa WHERE empresa_id=u.empresa_id AND d=ANY(holiday_dates));
 IF EXISTS(SELECT 1 FROM public.folha_registos other,jsonb_array_elements(other.intervals) x,jsonb_array_elements(p->'intervals') y
 WHERE other.data=d AND other.obra_id IS DISTINCT FROM w AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(plano) target WHERE target->>'work_id' IS NOT DISTINCT FROM other.obra_id::text) AND (CASE WHEN kind='primeline' THEN other.colaborador_id=person ELSE other.externo_id=person END)
 AND (x->>'start')::time<coalesce((y->>'end')::time,'24:00'::time) AND (y->>'start')::time<coalesce((x->>'end')::time,'24:00'::time))
 THEN RAISE EXCEPTION 'INTERVAL_CONFLICT: outra obra'; END IF;
 state:=folha_privado.estado_efetivo((f->>'minutes')::integer,(f->>'open')::boolean,expected,row->'absence'<>'null'::jsonb,row->>'conflict' IS NOT NULL);
 IF kind='external' THEN state:=CASE WHEN row->>'conflict' IS NOT NULL OR coalesce(row->'absence'<>'null'::jsonb,false) THEN 'regularization' WHEN (f->>'open')::boolean THEN 'open' ELSE 'registered' END; expected:=NULL; END IF;

 IF NOT confirmar THEN RETURN jsonb_build_object('before',to_jsonb(old),'revision',coalesce(old.revision,0),'row',row,'facts',f,'state',state); END IF;
 IF kind='external' THEN INSERT INTO public.folha_externos_dias(externo_id,empresa_id,obra_id,data,criado_por,request_id,funcao) SELECT person,u.empresa_id,w,d,u.id,req,funcao FROM public.folha_externos_permanencias WHERE externo_id=person AND obra_id=w AND inicio<=d AND (fim IS NULL OR fim>d) ON CONFLICT DO NOTHING; END IF;
 IF old.id IS NOT NULL THEN
 UPDATE public.folha_registos SET expected_minutes=expected,intervals=p->'intervals',minutes=(f->>'minutes')::integer,estado=state,special_day=old.special_day,special_reviewed_at=NULL,special_reviewed_by=NULL,
 revision=old.revision+1,note=p->>'note',atualizado_por=u.id,atualizado_em=now(),request_id=req WHERE id=old.id RETURNING * INTO result;
 ELSE
 INSERT INTO public.folha_registos(empresa_id,obra_id,tipo_local,data,colaborador_id,externo_id,intervals,minutes,estado,special_day,expected_minutes,revision,note,criado_por,atualizado_por,request_id)
 VALUES(u.empresa_id,w,CASE WHEN w IS NULL THEN 'escritorio' ELSE 'obra' END,d,CASE WHEN kind='primeline' THEN person END,CASE WHEN kind='external' THEN person END,p->'intervals',(f->>'minutes')::integer,state,special,expected,coalesce(old.revision,0)+1,p->>'note',u.id,u.id,req)
 RETURNING * INTO result;
 END IF;
 INSERT INTO public.folha_historico(empresa_id,obra_id,tipo_local,person_id,kind,data,action,antes,depois,revision,ator_id,request_id,reason)
 VALUES(u.empresa_id,w,CASE WHEN w IS NULL THEN 'escritorio' ELSE 'obra' END,person,kind,d,'save',to_jsonb(old),to_jsonb(result),result.revision,u.id,req,p->>'reason');
 
 RETURN jsonb_build_object('result',to_jsonb(result));
END $$;
CREATE FUNCTION folha_privado.referencia_plano_integrado_v3(p_acao text,p_dados jsonb,p_confirmar boolean,p_versao text,p_plano jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $reference$
DECLARE u public.utilizadores;req uuid:=(p_dados->>'request_id')::uuid;rid uuid:=(p_dados->>'id')::uuid;old public.folha_referencias;n public.folha_referencias;p uuid;d date;k text;f jsonb;xs jsonb;other jsonb;daily jsonb;payload jsonb;token text;outcome jsonb;op folha_privado.operacoes;cnt integer;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();IF (p_dados ? 'empresa_id' AND (p_dados->>'empresa_id')::uuid IS DISTINCT FROM u.empresa_id) OR (p_dados ? 'company_id' AND (p_dados->>'company_id')::uuid IS DISTINCT FROM u.empresa_id) THEN RAISE EXCEPTION 'TENANT_HINT_MISMATCH' USING ERRCODE='42501';END IF;PERFORM 1 FROM public.utilizadores WHERE id=u.id FOR SHARE;u:=folha_privado.ator();
 IF req IS NULL OR rid IS NULL OR p_confirmar IS NULL OR (p_dados->>'version')::integer IS DISTINCT FROM 3 OR p_acao IS NULL OR p_acao NOT IN('save_reference','associate_reference','special_review_reference') THEN RAISE EXCEPTION 'VALIDATION_ERROR';END IF;
 SELECT * INTO old FROM public.folha_referencias WHERE id=rid FOR UPDATE;IF old.id IS NOT NULL AND old.empresa_id<>u.empresa_id THEN RAISE EXCEPTION 'PERMISSION_DENIED' USING ERRCODE='42501';END IF;n:=old;
 IF old.id IS NULL THEN IF p_acao<>'save_reference' THEN RAISE EXCEPTION 'REFERENCE_NOT_FOUND';END IF;n.id:=rid;n.empresa_id:=u.empresa_id;k:=p_dados->>'kind';IF k='primeline' THEN n.colaborador_id:=(p_dados->>'person_id')::uuid;ELSIF k='external' THEN n.externo_id:=(p_dados->>'person_id')::uuid;ELSE RAISE EXCEPTION 'VALIDATION_ERROR';END IF;n.data:=(p_dados->>'date')::date;n.origem_obra_id:=(p_dados->>'origin_work_id')::uuid;n.tipo:=p_dados->>'type';n.referencia_original:=p_dados->>'original_reference';n.obra_original_id:=(p_dados->>'original_work_id')::uuid;n.criado_por:=u.id;n.criado_em:=now();n.special_day:=extract(isodow FROM n.data)>5 OR EXISTS(SELECT 1 FROM public.folha_config_empresa WHERE empresa_id=u.empresa_id AND n.data=ANY(holiday_dates));END IF;
 p:=coalesce(n.colaborador_id,n.externo_id);d:=n.data;k:=CASE WHEN n.colaborador_id IS NULL THEN 'external' ELSE 'primeline' END;PERFORM folha_privado.lock_dia(p,d);
 IF k='primeline' THEN PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id FOR SHARE;ELSE PERFORM 1 FROM public.folha_externos WHERE id=p AND empresa_id=u.empresa_id FOR SHARE;END IF;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: tenant pessoa' USING ERRCODE='42501';END IF;
 IF n.obra_original_id IS NOT NULL THEN PERFORM 1 FROM public.obras WHERE id=n.obra_original_id AND empresa_id=u.empresa_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: obra original' USING ERRCODE='42501';END IF;END IF;
 IF p_acao='save_reference' THEN PERFORM folha_privado.destino_autorizar_v3(p,n.origem_obra_id,k,true);IF k='primeline' THEN PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id AND data_admissao<=d AND (data_saida IS NULL OR data_saida>d) FOR UPDATE;ELSE PERFORM 1 FROM public.folha_externos WHERE id=p AND empresa_id=u.empresa_id AND (ativo OR (folha_privado.adm_operacional() OR u.funcao='diretor_obra') AND old.id IS NOT NULL) FOR UPDATE;END IF;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: pessoa' USING ERRCODE='42501';END IF;
  IF k='primeline' AND NOT folha_privado.adm_operacional() AND NOT folha_privado.elegivel_equipa(p,d) AND NOT EXISTS(SELECT 1 FROM public.colaboradores WHERE id=p AND utilizador_id=u.id AND u.funcao IN('encarregado','diretor_obra','adjunto','preparador')) THEN RAISE EXCEPTION 'PERMISSION_DENIED: equipa' USING ERRCODE='42501';END IF;
  IF d<(now() AT TIME ZONE 'Europe/Lisbon')::date-1 AND NOT folha_privado.adm_operacional() AND NOT(k='external' AND u.funcao='diretor_obra') THEN RAISE EXCEPTION 'CORRECTION_WINDOW_EXCEEDED';END IF;
 ELSE IF NOT folha_privado.adm_operacional() THEN RAISE EXCEPTION 'PERMISSION_DENIED: administrativo' USING ERRCODE='42501';END IF;END IF;
 IF (d<(now() AT TIME ZONE 'Europe/Lisbon')::date-1 OR p_acao<>'save_reference' OR k='external' AND u.funcao='diretor_obra') AND nullif(btrim(p_dados->>'reason'),'') IS NULL THEN RAISE EXCEPTION 'CORRECTION_REASON_REQUIRED';END IF;
 payload:=jsonb_build_object('action',p_acao,'data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 IF (p_dados->>'expected_revision')::integer IS DISTINCT FROM coalesce(old.revision,0) THEN RAISE EXCEPTION 'STALE_REVISION' USING ERRCODE='40001';END IF;
 IF p_acao='save_reference' THEN
  IF old.id IS NOT NULL AND (p_dados ? 'original_reference' AND p_dados->>'original_reference' IS DISTINCT FROM old.referencia_original OR p_dados ? 'origin_work_id' AND (p_dados->>'origin_work_id')::uuid IS DISTINCT FROM old.origem_obra_id OR p_dados ? 'person_id' AND (p_dados->>'person_id')::uuid IS DISTINCT FROM p) THEN RAISE EXCEPTION 'REFERENCE_ORIGINAL_IMMUTABLE';END IF;
  IF k='primeline' AND (EXISTS(SELECT 1 FROM public.ausencias WHERE colaborador_id=p AND data=d) OR EXISTS(SELECT 1 FROM public.ponto_pessoal_obra WHERE colaborador_id=p AND data=d)) THEN RAISE EXCEPTION 'REFERENCE_POINT_CONFLICT';END IF;
  IF k='primeline' AND EXISTS(SELECT 1 FROM public.folha_he h JOIN public.folha_registos f ON f.id=h.folha_id WHERE f.colaborador_id=p AND f.data=d) THEN RAISE EXCEPTION 'NORMAL_HE_REQUIRES_ADMIN_REVIEW';END IF;
  IF k='external' AND NOT EXISTS(SELECT 1 FROM public.folha_externos_dias WHERE externo_id=p AND obra_id=n.origem_obra_id AND data=d) AND NOT EXISTS(SELECT 1 FROM public.folha_externos_permanencias WHERE externo_id=p AND obra_id=n.origem_obra_id AND inicio<=d AND (fim IS NULL OR fim>d)) THEN RAISE EXCEPTION 'EXTERNAL_DAY_REQUIRED';END IF;
  IF jsonb_typeof(p_dados->'intervals') IS DISTINCT FROM 'array' OR EXISTS(SELECT 1 FROM jsonb_array_elements(p_dados->'intervals') x WHERE x->>'mode' IS NULL OR x->>'mode' NOT IN('normal','personalizado') OR x->>'mode'='personalizado' AND x->>'period' IS NOT NULL OR x->>'mode'='normal' AND coalesce(x->>'period','') NOT IN('manha','tarde')) THEN RAISE EXCEPTION 'PERIOD_REQUIRED';END IF;
  xs:=p_dados->'intervals';f:=folha_privado.facts(xs,d);
  SELECT coalesce(jsonb_agg(x),'[]') INTO other FROM (SELECT x FROM public.folha_registos r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_plano) target WHERE target->>'type'='obra' AND (target->>'work_id')::uuid IS NOT DISTINCT FROM r.obra_id) AND r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END UNION ALL SELECT x FROM public.folha_referencias r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.id<>rid AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p_plano) target WHERE target->>'type'='reference' AND (target->>'id')::uuid=r.id) AND r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) q;
  IF jsonb_array_length(other||xs)>16 THEN RAISE EXCEPTION 'INTERVAL_LIMIT';END IF;PERFORM folha_privado.facts(other||xs,d);
  n.intervals:=xs;n.minutes:=(f->>'minutes')::integer;n.open:=(f->>'open')::boolean;n.special_reviewed_by:=NULL;n.special_reviewed_at:=NULL;
 ELSIF p_acao='associate_reference' THEN n.associada_obra_id:=(p_dados->>'associate_work_id')::uuid;IF n.associada_obra_id IS NULL THEN RAISE EXCEPTION 'ASSOCIATION_REQUIRED';END IF;PERFORM 1 FROM public.obras WHERE id=n.associada_obra_id AND empresa_id=u.empresa_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: obra associação' USING ERRCODE='42501';END IF;n.associada_por:=u.id;n.associada_em:=now();
 ELSE IF NOT n.special_day THEN RAISE EXCEPTION 'NOT_SPECIAL_DAY';END IF;n.special_reviewed_by:=u.id;n.special_reviewed_at:=now();END IF;
 IF k='primeline' THEN SELECT to_jsonb(a) INTO daily FROM public.folha_avaliacoes_diarias a WHERE colaborador_id=p AND data=d AND empresa_id=u.empresa_id FOR UPDATE;IF (p_dados->>'expected_daily_revision')::integer IS DISTINCT FROM coalesce((daily->>'revision')::integer,0) THEN RAISE EXCEPTION 'STALE_REVISION: diária' USING ERRCODE='40001';END IF;END IF;
 n.revision:=coalesce(old.revision,0)+1;n.atualizado_por:=u.id;n.atualizado_em:=now();n.request_id:=req;
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'before',to_jsonb(old),'daily',daily,'source',(SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]') FROM (SELECT to_jsonb(r) value FROM public.folha_registos r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END UNION ALL SELECT to_jsonb(r) value FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) x),'reference',CASE WHEN k='primeline' AND daily IS NULL THEN folha_privado.diaria_referencia(p,d) END,'after',to_jsonb(n)-'criado_em'-'atualizado_em'-'associada_em'-'special_reviewed_at')::text,'UTF8')),'hex');
 IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'preview',to_jsonb(n));END IF;IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 IF old.id IS NULL THEN INSERT INTO public.folha_referencias SELECT(n).*;ELSE UPDATE public.folha_referencias SET intervals=n.intervals,minutes=n.minutes,open=n.open,associada_obra_id=n.associada_obra_id,associada_por=n.associada_por,associada_em=n.associada_em,special_reviewed_by=n.special_reviewed_by,special_reviewed_at=n.special_reviewed_at,revision=n.revision,atualizado_por=n.atualizado_por,atualizado_em=n.atualizado_em,request_id=req WHERE id=rid;END IF;
 INSERT INTO public.folha_referencias_historico(empresa_id,referencia_id,revision,action,antes,depois,ator_id,request_id,reason) VALUES(u.empresa_id,rid,n.revision,p_acao,to_jsonb(old),to_jsonb(n),u.id,req,p_dados->>'reason');
 outcome:=jsonb_build_object('version',3,'committed',true,'request_id',req,'reference',to_jsonb(n));INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,outcome,now());RETURN outcome;
END $reference$;
CREATE FUNCTION public.fn_folha_plano_integrado_v3(p_dados jsonb,p_confirmar boolean DEFAULT false,p_versao text DEFAULT NULL) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $plan$
DECLARE u public.utilizadores;p uuid:=(p_dados->>'person_id')::uuid;d date:=(p_dados->>'date')::date;k text:=p_dados->>'kind';w uuid:=(p_dados->>'work_id')::uuid;req uuid:=(p_dados->>'request_id')::uuid;sites jsonb:=p_dados->'sites';s jsonb;xs jsonb;unchanged jsonb;source jsonb;ev jsonb;ref public.folha_referencias;body jsonb;pre jsonb;preview jsonb:='[]';payload jsonb;token text;result jsonb;results jsonb:='[]';op folha_privado.operacoes;rev integer;count_unchanged integer;day_summary jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'RETRY_READ_COMMITTED' USING ERRCODE='40001';END IF;
 LOCK TABLE public.quadro_pessoal_alocacao IN ROW EXCLUSIVE MODE;PERFORM pg_advisory_xact_lock(61001,1);u:=folha_privado.ator();IF (p_dados ? 'empresa_id' AND (p_dados->>'empresa_id')::uuid IS DISTINCT FROM u.empresa_id) OR (p_dados ? 'company_id' AND (p_dados->>'company_id')::uuid IS DISTINCT FROM u.empresa_id) THEN RAISE EXCEPTION 'TENANT_HINT_MISMATCH' USING ERRCODE='42501';END IF;PERFORM folha_privado.destino_autorizar_v3(p,w,k,true);PERFORM folha_privado.lock_dia(p,d);
 IF req IS NULL OR p IS NULL OR d IS NULL OR k IS NULL OR k NOT IN('primeline','external') OR p_confirmar IS NULL OR (p_dados->>'version')::integer IS DISTINCT FROM 3 OR jsonb_typeof(sites) IS DISTINCT FROM 'array' OR jsonb_array_length(sites) NOT BETWEEN 1 AND 4 OR EXISTS(SELECT 1 FROM jsonb_array_elements(sites) x WHERE x->>'type' IS NULL OR x->>'type' NOT IN('obra','reference') OR jsonb_typeof(x->'intervals') IS DISTINCT FROM 'array' OR jsonb_array_length(x->'intervals') NOT BETWEEN 1 AND 16) OR EXISTS(SELECT 1 FROM jsonb_array_elements(sites) x GROUP BY x->>'type',CASE WHEN x->>'type'='obra' THEN x->>'work_id' ELSE x->>'id' END HAVING count(*)>1) THEN RAISE EXCEPTION 'PLAN_INVALID';END IF;
 IF k='primeline' THEN PERFORM 1 FROM public.colaboradores WHERE id=p AND empresa_id=u.empresa_id AND data_admissao<=d AND (data_saida IS NULL OR data_saida>d) FOR UPDATE;ELSE PERFORM 1 FROM public.folha_externos e JOIN public.fornecedores provider ON provider.id=e.fornecedor_id WHERE e.id=p AND e.empresa_id=u.empresa_id AND provider.empresa_id=u.empresa_id AND (e.ativo OR (folha_privado.adm_operacional() OR u.funcao='diretor_obra') AND EXISTS(SELECT 1 FROM public.folha_registos existing WHERE existing.externo_id=p AND existing.data=d AND existing.empresa_id=u.empresa_id)) FOR UPDATE OF e;END IF;IF NOT FOUND THEN RAISE EXCEPTION 'PERMISSION_DENIED: pessoa' USING ERRCODE='42501';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(sites) ORDER BY value->>'type',coalesce(value->>'work_id',value->>'id') LOOP
  IF s->>'type'='obra' THEN IF s->>'work_id' IS NULL THEN RAISE EXCEPTION 'DESTINATION_REQUIRED';END IF;PERFORM folha_privado.destino_autorizar_v3(p,(s->>'work_id')::uuid,k,true);
  ELSE IF s->>'id' IS NULL THEN RAISE EXCEPTION 'REFERENCE_REQUIRED';END IF;PERFORM folha_privado.destino_autorizar_v3(p,(s->>'origin_work_id')::uuid,k,true);SELECT * INTO ref FROM public.folha_referencias WHERE id=(s->>'id')::uuid FOR UPDATE;IF ref.id IS NOT NULL AND (ref.empresa_id<>u.empresa_id OR ref.data<>d OR coalesce(ref.colaborador_id,ref.externo_id)<>p OR (ref.colaborador_id IS NULL)<>(k='external')) THEN RAISE EXCEPTION 'PERMISSION_DENIED: referência' USING ERRCODE='42501';END IF;END IF;
 END LOOP;
 payload:=jsonb_build_object('action','integrated_plan','data',p_dados);SELECT * INTO op FROM folha_privado.operacoes WHERE empresa_id=u.empresa_id AND ator_id=u.id AND request_id=req;
 IF FOUND THEN IF op.payload IS DISTINCT FROM payload THEN RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT';END IF;IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',op.token);END IF;IF p_versao IS DISTINCT FROM op.token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;RETURN op.resultado;END IF;
 IF k='primeline' THEN SELECT to_jsonb(a) INTO ev FROM public.folha_avaliacoes_diarias a WHERE colaborador_id=p AND data=d AND empresa_id=u.empresa_id FOR UPDATE;IF (p_dados->>'expected_daily_revision')::integer IS DISTINCT FROM coalesce((ev->>'revision')::integer,0) THEN RAISE EXCEPTION 'STALE_REVISION: diária' USING ERRCODE='40001';END IF;END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY to_jsonb(x)::text),'[]') INTO source FROM (SELECT to_jsonb(f) value FROM public.folha_registos f WHERE f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END UNION ALL SELECT to_jsonb(r) value FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END) x;
 SELECT coalesce(jsonb_agg(x),'[]') INTO unchanged FROM (SELECT x FROM public.folha_registos f CROSS JOIN LATERAL jsonb_array_elements(f.intervals) x WHERE f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target WHERE target->>'type'='obra' AND (target->>'work_id')::uuid IS NOT DISTINCT FROM f.obra_id) UNION ALL SELECT x FROM public.folha_referencias r CROSS JOIN LATERAL jsonb_array_elements(r.intervals) x WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target WHERE target->>'type'='reference' AND (target->>'id')::uuid=r.id)) q;
 SELECT coalesce(jsonb_agg(x),'[]') INTO xs FROM jsonb_array_elements(sites) target CROSS JOIN LATERAL jsonb_array_elements(target->'intervals') x;
 xs:=xs||unchanged;IF jsonb_array_length(xs)>16 THEN RAISE EXCEPTION 'INTERVAL_LIMIT';END IF;PERFORM folha_privado.facts(xs,d);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target CROSS JOIN LATERAL jsonb_array_elements(target->'intervals') x WHERE x ? 'daily_scope' OR x->>'mode' IS NULL OR x->>'mode' NOT IN('normal','personalizado') OR x->>'mode'='personalizado' AND x->>'period' IS NOT NULL OR x->>'mode'='normal' AND coalesce(x->>'period','') NOT IN('manha','tarde')) THEN RAISE EXCEPTION 'PERIOD_REQUIRED';END IF;
 SELECT count(*) INTO count_unchanged FROM (SELECT f.id FROM public.folha_registos f WHERE f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target WHERE target->>'type'='obra' AND (target->>'work_id')::uuid IS NOT DISTINCT FROM f.obra_id) UNION ALL SELECT r.id FROM public.folha_referencias r WHERE r.data=d AND CASE WHEN k='primeline' THEN r.colaborador_id=p ELSE r.externo_id=p END AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(sites) target WHERE target->>'type'='reference' AND (target->>'id')::uuid=r.id)) q;IF count_unchanged+jsonb_array_length(sites)>4 THEN RAISE EXCEPTION 'DESTINATION_LIMIT';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(sites) ORDER BY value->>'type',coalesce(value->>'work_id',value->>'id') LOOP
  IF s->>'type'='obra' THEN
   IF EXISTS(SELECT 1 FROM public.obras WHERE id=(s->>'work_id')::uuid AND situacao<>'em_curso') AND NOT EXISTS(SELECT 1 FROM public.folha_registos f WHERE f.obra_id=(s->>'work_id')::uuid AND f.data=d AND CASE WHEN k='primeline' THEN f.colaborador_id=p ELSE f.externo_id=p END) THEN RAISE EXCEPTION 'DESTINATION_NOT_ACTIVE';END IF;
   body:=jsonb_build_object('key',jsonb_build_object('kind',k,'person_id',p,'date',d,'work_id',s->>'work_id'),'expected_revision',s->'expected_revision','intervals',CASE WHEN k='primeline' THEN (SELECT jsonb_agg(x||jsonb_build_object('daily_scope',true) ORDER BY n) FROM jsonb_array_elements(s->'intervals') WITH ORDINALITY t(x,n)) ELSE s->'intervals' END,'reason',p_dados->>'reason','note',p_dados->>'note');pre:=folha_privado.save_plano_integrado_v3(body,(s->>'work_id')::uuid,d,req,false,sites);
  ELSE
   body:=jsonb_build_object('version',3,'request_id',md5(req::text||':'||(s->>'id'))::uuid,'id',s->>'id','kind',k,'person_id',p,'date',d,'origin_work_id',s->>'origin_work_id','type',s->>'reference_type','original_reference',s->>'original_reference','original_work_id',s->>'original_work_id','expected_revision',s->'expected_revision','expected_daily_revision',p_dados->'expected_daily_revision','intervals',s->'intervals','reason',p_dados->>'reason');pre:=folha_privado.referencia_plano_integrado_v3('save_reference',body,false,NULL,sites);
  END IF;preview:=preview||jsonb_build_array(jsonb_build_object('type',s->>'type','identity',coalesce(s->>'work_id',s->>'id'),'data',CASE WHEN s->>'type'='reference' THEN jsonb_build_object('versao',pre->>'versao') ELSE pre END));
 END LOOP;
 token:=encode(sha256(convert_to(jsonb_build_object('actor',u.id,'tenant',u.empresa_id,'payload',payload,'source',source,'daily',ev,'reference',CASE WHEN k='primeline' AND ev IS NULL THEN folha_privado.diaria_referencia(p,d) END,'previews',preview)::text,'UTF8')),'hex');IF NOT p_confirmar THEN RETURN jsonb_build_object('version',3,'committed',false,'versao',token,'targets',jsonb_array_length(sites),'minutes',(folha_privado.facts(xs,d)->>'minutes')::integer);END IF;IF p_versao IS DISTINCT FROM token THEN RAISE EXCEPTION 'STALE_PREVIEW' USING ERRCODE='40001';END IF;
 FOR s IN SELECT value FROM jsonb_array_elements(sites) ORDER BY value->>'type',coalesce(value->>'work_id',value->>'id') LOOP
  IF s->>'type'='obra' THEN body:=jsonb_build_object('key',jsonb_build_object('kind',k,'person_id',p,'date',d,'work_id',s->>'work_id'),'expected_revision',s->'expected_revision','intervals',CASE WHEN k='primeline' THEN (SELECT jsonb_agg(x||jsonb_build_object('daily_scope',true) ORDER BY n) FROM jsonb_array_elements(s->'intervals') WITH ORDINALITY t(x,n)) ELSE s->'intervals' END,'reason',p_dados->>'reason','note',p_dados->>'note');result:=folha_privado.save_plano_integrado_v3(body,(s->>'work_id')::uuid,d,req,true,sites);results:=results||jsonb_build_array(jsonb_build_object('type','obra','record',result->'result'));
  ELSE IF k='primeline' THEN SELECT coalesce((SELECT revision FROM public.folha_avaliacoes_diarias WHERE colaborador_id=p AND data=d),0) INTO rev;END IF;
   body:=jsonb_build_object('version',3,'request_id',md5(req::text||':'||(s->>'id'))::uuid,'id',s->>'id','kind',k,'person_id',p,'date',d,'origin_work_id',s->>'origin_work_id','type',s->>'reference_type','original_reference',s->>'original_reference','original_work_id',s->>'original_work_id','expected_revision',s->'expected_revision','expected_daily_revision',rev,'intervals',s->'intervals','reason',p_dados->>'reason');pre:=folha_privado.referencia_plano_integrado_v3('save_reference',body,false,NULL,sites);result:=folha_privado.referencia_plano_integrado_v3('save_reference',body,true,pre->>'versao',sites);results:=results||jsonb_build_array(jsonb_build_object('type','reference','reference',result->'reference'));
  END IF;
 END LOOP;
 IF k='primeline' THEN result:=folha_privado.diaria_recalcular(p,d,req);day_summary:=jsonb_build_object('revision',result->'revision','mode',result->'modo_dia','state',result->'estado','minutes',result->'realizado_minutes','expected_minutes',result->'expected_minutes','reference_state',result->'referencia_estado','he_state',result->'he_estado','pending',result->'pendencias');END IF;
 result:=jsonb_build_object('version',3,'committed',true,'request_id',req,'results',results,'daily_summary',day_summary);INSERT INTO folha_privado.operacoes VALUES(u.empresa_id,u.id,req,payload,token,result,now());RETURN result;
END $plan$;

REVOKE ALL ON FUNCTION folha_privado.save_plano_integrado_v3(jsonb,uuid,date,uuid,boolean,jsonb),folha_privado.referencia_plano_integrado_v3(text,jsonb,boolean,text,jsonb),public.fn_folha_plano_integrado_v3(jsonb,boolean,text) FROM PUBLIC,anon,authenticated,service_role;GRANT EXECUTE ON FUNCTION public.fn_folha_plano_integrado_v3(jsonb,boolean,text) TO authenticated;DO $hours_dependencies$ BEGIN
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.ator()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='176c4fb030401fb45c89f3cd1616a9d26e9e15b691ff524a33dfc8d233c6b079' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.ator()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.obra(uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='731f5289cd29bdb7f7d69723fabb76cbb8b8e577bb474c679f991c7271d9788e' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.obra(uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.lock_dia(uuid,date)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='b29022304f316e25dd34bae7a1e1906a0dfd72bd041a1d658338cc8394745502' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.lock_dia(uuid,date)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.local(uuid,uuid,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='9eb2f0d8b7e52d5280f0798c48cb8ec84377281c1e13706bc066b1cf3765070b' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner )) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: folha_privado.local(uuid,uuid,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('public.fn_folha_contexto_v2(date,uuid)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e5ca6e224708a655a9c778fa6a5701b39e6c0aab8dbf0a01a87ffb77d42ea095' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) x WHERE x.grantee<>proowner AND x.grantee<>'authenticated'::regrole)) THEN RAISE EXCEPTION 'HORAS_AUTHORIZATION_DEPENDENCY_DRIFT: public.fn_folha_contexto_v2(date,uuid)';END IF;
END $hours_dependencies$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.destino_autorizar_v3(uuid,uuid,text,boolean)') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='c874fba357c974db5241fc0c5c82bf92a2f012e822f8d0fb545b0f18317daa22' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner )) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: folha_privado.destino_autorizar_v3(uuid,uuid,text,boolean)';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.referencia_guardar_v3()') AND proowner='postgres'::regrole AND prosecdef=false AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='e4314ef9836ce96178a50843f8fda176d82210349da6172ae318ea001b07bc2d' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner )) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: folha_privado.referencia_guardar_v3()';END IF;
IF NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=to_regprocedure('folha_privado.referencia_invariante_v3()') AND proowner='postgres'::regrole AND prosecdef=true AND proconfig=ARRAY['search_path=pg_catalog'] AND encode(sha256(convert_to(replace(prosrc,chr(13),''),'UTF8')),'hex')='df2584770792c8f77a6d9c5dc50bd6714ff353671574cf2f94fe2f76b88b0e1a' AND NOT EXISTS(SELECT 1 FROM aclexplode(coalesce(proacl,acldefault('f',proowner))) a WHERE a.grantee<>proowner )) THEN RAISE EXCEPTION 'ADDON_FUNCTION_DRIFT: folha_privado.referencia_invariante_v3()';END IF;END $functions$;DO $functions$ BEGIN IF current_user<>'postgres' OR session_user<>'postgres' THEN RAISE EXCEPTION 'OWNER_REQUIRED';END IF;
